gsdBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "gsdBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmsequential",
                name = "gsd",
                version = c(0,1,0),
                options = options,
                results = gsdResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Group Sequential Design
#'
#' Design of a group sequential study: efficacy boundaries (classical, 
#' error-spending or Whitehead's triangular test), optional futility 
#' boundaries, operating characteristics and the sample size or number of 
#' events, including survival designs with accrual, follow-up and dropout.
#' @param data .
#' @param lookN .
#' @param estimate .
#' @param se .
#' @param zStat .
#' @param infoFrac .
#' @param finalLook .
#' @param endpoint .
#' @param sided .
#' @param alpha .
#' @param power .
#' @param nLooks .
#' @param timing .
#' @param ratio .
#' @param meanDiff .
#' @param sd .
#' @param p0 .
#' @param p1 .
#' @param genEffect .
#' @param genSd .
#' @param hr .
#' @param ctrlSpec .
#' @param ctrlMedian .
#' @param ctrlHazard .
#' @param survTime .
#' @param survProb .
#' @param eventsMethod .
#' @param solveFor .
#' @param accrualTime .
#' @param accrualRate .
#' @param followUp .
#' @param nTotal .
#' @param dropoutProb .
#' @param dropoutTime .
#' @param efficacy .
#' @param effRho .
#' @param effGamma .
#' @param effNu .
#' @param effUser .
#' @param wtDelta .
#' @param hpZ .
#' @param ptDelta1 .
#' @param ptDelta0 .
#' @param futility .
#' @param futSf .
#' @param futRho .
#' @param futGamma .
#' @param futNu .
#' @param futZ .
#' @param futCp .
#' @param futCpUnder .
#' @param binding .
#' @param ocTable .
#' @param boundPlot .
#' @param boundScale .
#' @param boundX .
#' @param spendPlot .
#' @param powerPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bounds} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$oc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$timing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$boundPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$spendPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$powerPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$monitor} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$final} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monitorPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
gsd <- function(
    data,
    lookN = NULL,
    estimate = NULL,
    se = NULL,
    zStat = NULL,
    infoFrac = NULL,
    finalLook = FALSE,
    endpoint = "means",
    sided = "one",
    alpha = 0.025,
    power = 0.9,
    nLooks = 3,
    timing = "",
    ratio = 1,
    meanDiff = 0.5,
    sd = 1,
    p0 = 0.3,
    p1 = 0.45,
    genEffect = 0.5,
    genSd = 1,
    hr = 0.7,
    ctrlSpec = "median",
    ctrlMedian = 12,
    ctrlHazard = 0.0578,
    survTime = 12,
    survProb = 0.5,
    eventsMethod = "schoenfeld",
    solveFor = "n",
    accrualTime = 24,
    accrualRate = 20,
    followUp = 12,
    nTotal = 600,
    dropoutProb = 0,
    dropoutTime = 12,
    efficacy = "ldof",
    effRho = 3,
    effGamma = -4,
    effNu = 0.75,
    effUser = "",
    wtDelta = 0.25,
    hpZ = 3,
    ptDelta1 = 0,
    ptDelta0 = 0,
    futility = "none",
    futSf = "hsd",
    futRho = 2,
    futGamma = -2,
    futNu = 0.75,
    futZ = "0",
    futCp = 0.2,
    futCpUnder = "trend",
    binding = FALSE,
    ocTable = TRUE,
    boundPlot = TRUE,
    boundScale = "z",
    boundX = "n",
    spendPlot = FALSE,
    powerPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("gsd requires jmvcore to be installed (restart may be required)")

    if ( ! missing(lookN)) lookN <- jmvcore::resolveQuo(jmvcore::enquo(lookN))
    if ( ! missing(estimate)) estimate <- jmvcore::resolveQuo(jmvcore::enquo(estimate))
    if ( ! missing(se)) se <- jmvcore::resolveQuo(jmvcore::enquo(se))
    if ( ! missing(zStat)) zStat <- jmvcore::resolveQuo(jmvcore::enquo(zStat))
    if ( ! missing(infoFrac)) infoFrac <- jmvcore::resolveQuo(jmvcore::enquo(infoFrac))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(lookN), lookN, NULL),
            `if`( ! missing(estimate), estimate, NULL),
            `if`( ! missing(se), se, NULL),
            `if`( ! missing(zStat), zStat, NULL),
            `if`( ! missing(infoFrac), infoFrac, NULL))


    options <- gsdOptions$new(
        lookN = lookN,
        estimate = estimate,
        se = se,
        zStat = zStat,
        infoFrac = infoFrac,
        finalLook = finalLook,
        endpoint = endpoint,
        sided = sided,
        alpha = alpha,
        power = power,
        nLooks = nLooks,
        timing = timing,
        ratio = ratio,
        meanDiff = meanDiff,
        sd = sd,
        p0 = p0,
        p1 = p1,
        genEffect = genEffect,
        genSd = genSd,
        hr = hr,
        ctrlSpec = ctrlSpec,
        ctrlMedian = ctrlMedian,
        ctrlHazard = ctrlHazard,
        survTime = survTime,
        survProb = survProb,
        eventsMethod = eventsMethod,
        solveFor = solveFor,
        accrualTime = accrualTime,
        accrualRate = accrualRate,
        followUp = followUp,
        nTotal = nTotal,
        dropoutProb = dropoutProb,
        dropoutTime = dropoutTime,
        efficacy = efficacy,
        effRho = effRho,
        effGamma = effGamma,
        effNu = effNu,
        effUser = effUser,
        wtDelta = wtDelta,
        hpZ = hpZ,
        ptDelta1 = ptDelta1,
        ptDelta0 = ptDelta0,
        futility = futility,
        futSf = futSf,
        futRho = futRho,
        futGamma = futGamma,
        futNu = futNu,
        futZ = futZ,
        futCp = futCp,
        futCpUnder = futCpUnder,
        binding = binding,
        ocTable = ocTable,
        boundPlot = boundPlot,
        boundScale = boundScale,
        boundX = boundX,
        spendPlot = spendPlot,
        powerPlot = powerPlot)

    analysis <- gsdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

